-- Preserve the existing restrictive live-session policy and SELECT scope.
drop policy ts_pro_grants_admin on public.ts_pro_grants;
create policy ts_pro_grants_admin_insert on public.ts_pro_grants for insert to authenticated with check (exists (select 1 from public.ts_profiles p where p.user_id=(select auth.uid()) and p.active and p.role='admin'));
create policy ts_pro_grants_admin_update on public.ts_pro_grants for update to authenticated using (exists (select 1 from public.ts_profiles p where p.user_id=(select auth.uid()) and p.active and p.role='admin')) with check (exists (select 1 from public.ts_profiles p where p.user_id=(select auth.uid()) and p.active and p.role='admin'));
create policy ts_pro_grants_admin_delete on public.ts_pro_grants for delete to authenticated using (exists (select 1 from public.ts_profiles p where p.user_id=(select auth.uid()) and p.active and p.role='admin'));
